<template>
 <main class="collection-page"><header class="collection-heading"><div><span class="collection-kicker">{{ config.kicker }}</span><h1>{{ config.title }}</h1><p>{{ config.description }}</p></div><span class="collection-count">{{ total }} <small>{{ config.unit }}</small></span></header>
 <form class="collection-toolbar" @submit.prevent="search"><div class="collection-categories" v-if="type==='sheyingshixinxi'"><button type="button" :class="{active:!category}" @click="choose('')">全部风格</button><button v-for="item in categories" :key="item" type="button" :class="{active:category===item}" @click="choose(item)">{{ item }}</button></div><span v-else class="collection-label">{{ config.label }}</span><div class="collection-search"><el-input v-model="keyword" :placeholder="config.placeholder" clearable @clear="search" aria-label="搜索内容" /><el-button native-type="submit" :loading="loading">搜索 ↗</el-button></div></form>
 <div v-if="failed" class="collection-error"><p>内容暂时加载失败</p><el-button @click="load">重新加载</el-button></div>
 <div v-else-if="loading" class="collection-grid" aria-busy="true"><el-skeleton v-for="n in 6" :key="n" animated><template #template><el-skeleton-item variant="image" style="width:100%;height:280px"/><el-skeleton-item style="margin-top:20px;width:60%"/></template></el-skeleton></div>
 <div v-else-if="items.length" :class="['collection-grid',{'portrait-grid':type==='sheyingshixinxi'}]"><article v-for="(item,index) in items" :key="item.id" class="collection-card"><router-link class="collection-image" :to="destination(item.id)" :aria-label="item[config.name]"><img :src="image(item[config.image])" :alt="item[config.name]" loading="lazy"/><span class="collection-image-index">{{ String((page-1)*9+index+1).padStart(2,'0') }}</span><span class="collection-image-action">{{ type==='sheyingshixinxi' ? '了解摄影师' : '查看详情' }} ↗</span></router-link><div class="collection-meta"><span>{{ type==='sheyingshixinxi' ? item.fenlei || '独立摄影师' : type==='huodongxinxi' ? item.kaishishijian?.slice(0,10) || '摄影活动' : item.sheyingxingming || '花海影像' }}</span><span v-if="type==='sheyingshixinxi' && item.yuyuejiage!=null">¥ {{ item.yuyuejiage }}</span><span v-else>{{ type==='huodongxinxi' ? 'EVENT' : 'PHOTOGRAPHY' }}</span></div><h2><router-link :to="destination(item.id)">{{ item[config.name] }}</router-link></h2><p class="collection-summary">{{ type==='sheyingshixinxi' ? plain(item.jianjie) : type==='huodongxinxi' ? item.huodongdidian || '查看活动安排' : plain(item.zuopinjianjie) }}</p><router-link v-if="type==='sheyingshixinxi'" class="collection-book" :to="destination(item.id)">查看作品与预约档期 <span>↗</span></router-link></article></div>
 <el-empty v-else description="没有找到相关内容，试试其他关键词吧" />
 <footer class="collection-pagination"><span>每一次发现，都可能是下一次拍摄的灵感。</span><el-pagination v-if="total>9" v-model:current-page="page" :page-size="9" :total="total" layout="prev, pager, next" @current-change="load" /></footer></main>
</template>
<script setup>
import {computed,ref,getCurrentInstance,watch} from 'vue'
const props=defineProps({type:{type:String,required:true}})
const context=getCurrentInstance().appContext.config.globalProperties
const definitions={sheyingzuopin:{kicker:'THE VISUAL JOURNAL',title:'作品集',description:'让影像说话，在光影与情绪之间，发现你的拍摄灵感。',unit:'组作品',label:'精选影像 / ALL STORIES',placeholder:'搜索作品名称',name:'zuopinmingcheng',image:'zuopintupian',query:'zuopinmingcheng'},sheyingshixinxi:{kicker:'PEOPLE BEHIND THE LENS',title:'摄影师',description:'不同的视角，同样的热爱。找到与你审美同频的拍摄伙伴。',unit:'位摄影师',placeholder:'搜索摄影师姓名',name:'sheyingxingming',image:'sheyingshizhaopian',query:'sheyingxingming'},huodongxinxi:{kicker:'MEET · EXPLORE · CREATE',title:'一起，去发现',description:'走出日常，在一次次相遇与探索中，留下新的影像故事。',unit:'场活动',label:'活动与灵感 / STUDIO EVENTS',placeholder:'搜索活动名称',name:'huodongmingcheng',image:'huodongtupian',query:'huodongmingcheng'}}
const config=computed(()=>definitions[props.type])
const items=ref([]),total=ref(0),page=ref(1),keyword=ref(''),category=ref(''),categories=ref([]),loading=ref(false),failed=ref(false)
let sequence=0
const destination=id=>'/index/'+props.type+'Detail?id='+id
const image=value=>{const first=(value||'').split(',')[0];return /^https?:/.test(first)?first:first?context.$config.url+first:''}
const plain=value=>{const node=document.createElement('div');node.innerHTML=value||'';return node.textContent||''}
function search(){page.value=1;load()}
function choose(value){category.value=value;search()}
async function load(){const request=++sequence;loading.value=true;failed.value=false;try{const params={page:page.value,limit:9,sort:'id',order:'desc'};if(keyword.value.trim())params[config.value.query]='%'+keyword.value.trim()+'%';if(props.type==='sheyingshixinxi'){params.sfsh='是';if(category.value)params.fenlei=category.value}const result=await context.$http.get(props.type+'/list',{params});if(request===sequence){items.value=result.data.data.list;total.value=Number(result.data.data.total)}}catch{if(request===sequence)failed.value=true}finally{if(request===sequence)loading.value=false}}
watch(()=>props.type,async()=>{page.value=1;keyword.value='';category.value='';load();if(props.type==='sheyingshixinxi')try{const result=await context.$http.get('option/fenlei/fenlei');categories.value=result.data.data}catch{categories.value=[]}},{immediate:true})
</script>
<style scoped>
.collection-page{max-width:1200px;width:calc(100% - 80px);margin:0 auto;padding:66px 0 56px;color:#25382e;box-sizing:border-box}.collection-page *{box-sizing:border-box}.collection-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;padding:0 0 44px}.collection-kicker{color:#939b87;font-size:10px;letter-spacing:3px}.collection-heading h1{font-family:SimSun,serif;font-size:48px;letter-spacing:5px;font-weight:400;margin:20px 0}.collection-heading p{font-size:13px;line-height:1.9;color:#7b8575;margin:0}.collection-count{font-family:Georgia,serif;font-size:38px;color:#8b967e;white-space:nowrap}.collection-count small{font-family:inherit;font-size:12px;color:#8a9282;margin-left:8px}.collection-toolbar{border-top:1px solid #dfe4d8;border-bottom:1px solid #dfe4d8;padding:20px 0;margin:0 0 36px;display:flex;justify-content:space-between;align-items:center;gap:20px}.collection-label{font-size:10px;letter-spacing:2px;color:#8b9480}.collection-search{display:flex;gap:8px;min-width:300px}.collection-search .el-input{width:235px}.collection-search :deep(.el-input__wrapper){box-shadow:none;border-bottom:1px solid #dce1d5;background:transparent;border-radius:0}.collection-search .el-button{border:0;background:transparent;color:#305d4c}.collection-categories{display:flex;flex-wrap:wrap;gap:8px}.collection-categories button{border:0;background:transparent;color:#7f8976;cursor:pointer;padding:8px 12px;border-radius:3px;font-size:12px}.collection-categories button.active{background:#305d4c;color:white}.collection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:42px 28px}.collection-card{min-width:0}.collection-image{display:block;position:relative;aspect-ratio:4/3;background:#e9ebe4;overflow:hidden}.portrait-grid .collection-image{aspect-ratio:4/4.4}.collection-image img{width:100%;height:100%;object-fit:cover;transition:transform .5s}.collection-image:hover img{transform:scale(1.035)}.collection-image-index{position:absolute;top:16px;left:16px;color:#fff;font-size:11px;letter-spacing:2px;text-shadow:0 1px 5px #000}.collection-image-action{position:absolute;right:14px;bottom:14px;background:#faf9f6f0;color:#34513f;padding:9px 12px;font-size:11px}.collection-meta{display:flex;justify-content:space-between;gap:12px;margin-top:18px;font-size:10px;letter-spacing:1px;color:#8a947e}.collection-card h2{font-size:20px;font-weight:400;letter-spacing:1px;margin:12px 0}.collection-card h2 a{color:#283f30;text-decoration:none}.collection-summary{font-size:12px;line-height:1.9;color:#858e7c;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:0}.collection-book{display:flex;justify-content:space-between;border-top:1px solid #e2e6db;margin-top:20px;padding-top:16px;color:#476344;text-decoration:none;font-size:12px}.collection-pagination{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:54px;border-top:1px solid #e2e6db;padding-top:26px}.collection-pagination>span{color:#9aA18f;font-size:11px}.collection-error{padding:80px;text-align:center;color:#7f8976}@media(max-width:900px){.collection-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.collection-toolbar{align-items:flex-start;flex-direction:column}.collection-search{width:100%}.collection-search .el-input{width:100%}}@media(max-width:560px){.collection-page{width:calc(100% - 40px);padding-top:38px}.collection-heading h1{font-size:36px}.collection-heading{align-items:flex-start;padding-bottom:28px}.collection-count{font-size:24px;padding-top:30px}.collection-count small{display:block;font-size:10px}.collection-grid{grid-template-columns:1fr;gap:32px}.collection-pagination{flex-direction:column;align-items:flex-start}.collection-search{min-width:0}.collection-heading p{max-width:260px}.portrait-grid .collection-image{aspect-ratio:4/4}}
</style>
